import{_ as i,C as t,o,c as s,E as r,a2 as l}from"./chunks/framework.Cc8dJFaW.js";const d="/joinwell52/assets/receipt-binding-20261127/receipt.zh.png",p="/joinwell52/assets/receipt-binding-20261127/reprice.zh.png",f=JSON.parse('{"title":"500 元的订单，收到了 790 元的回执。AI 员工该再订一笔吗？","description":"正式改价后，接班 AI 怎样判断该沿用原单、补订，还是继续查？两轮 CodeFlowMu 对照记录了 Agent 的实际行动和订单账本。","frontmatter":{"title":"500 元的订单，收到了 790 元的回执。AI 员工该再订一笔吗？","description":"正式改价后，接班 AI 怎样判断该沿用原单、补订，还是继续查？两轮 CodeFlowMu 对照记录了 Agent 的实际行动和订单账本。","cover":"/assets/covers/2026-11-27-receipt-binding.png","date":"2026-11-27","published_date":"2026-11-27","column":"digital-employee","category":"daily","article_type":"experiment-report","edition":"research-center","language":"zh-CN","lifecycle":"Published","publication_authorized":true,"lang":"zh-CN","pageClass":"six-governance-article"},"headers":[],"relativePath":"zh/research/2026-11-27-receipt-binding.md","filePath":"zh/research/2026-11-27-receipt-binding.md","lastUpdated":null}'),c={name:"zh/research/2026-11-27-receipt-binding.md"};function h(g,e,u,b,_,m){const a=t("ArticleCover"),n=t("ArticleTableScroll");return o(),s("div",null,[r(a,{image:"/assets/covers/2026-11-27-receipt-binding.png",kicker:"数字员工 · 交接与复核",title:"500 元的订单，收到了 790 元的回执。AI 员工该再订一笔吗？",summary:"正式改价后，接班 AI 怎样判断该沿用原单、补订，还是继续查？两轮 CodeFlowMu 对照记录了 Agent 的实际行动和订单账本。",version:"2026-11-27",languageHref:"/en/research/2026-11-27-receipt-binding",languageLabel:"English"}),r(n,{language:"zh"}),e[0]||(e[0]=l('<h1 id="_500-元的订单-收到了-790-元的回执。ai-员工该再订一笔吗" tabindex="-1">500 元的订单，收到了 790 元的回执。AI 员工该再订一笔吗？ <a class="header-anchor" href="#_500-元的订单-收到了-790-元的回执。ai-员工该再订一笔吗" aria-label="Permalink to &quot;500 元的订单，收到了 790 元的回执。AI 员工该再订一笔吗？&quot;">​</a></h1><p>一名 AI 数字员工接过租车工单。上一班提交订单时等不到回信，本地没有留下可用的发送记录。工单上写的是 <strong>500 元</strong>，订单列表也是空的。接班员工拿着原请求号去查，终于收到回复：<strong>已提交，790 元。</strong></p><p>请求号是对的。要是你在接这张单，会把它标为完成，重新订一笔 500 元的车，还是把差异记下来，继续查原单？</p><p>这个选择在实验里造成了可见的后果。有一次，接班员工明明发现了金额差异，仍然新建了一笔订单。等它写完报告，我们从另一侧读账本，发现同一张工单已经对应两笔订单。</p><h2 id="为什么我们把金额换掉" tabindex="-1">为什么我们把金额换掉 <a class="header-anchor" href="#为什么我们把金额换掉" aria-label="Permalink to &quot;为什么我们把金额换掉&quot;">​</a></h2><p>在 CrewAI 的公开讨论里，一位贡献者演示过一种重试陷阱。工具如果只凭订单编号识别重复请求，就可能把金额已改的新请求当成旧请求，直接返回上一次的结果。他的实验给订单编号加上了参数指纹，金额变化时便能报告冲突。<a href="https://github.com/crewAIInc/crewAI/issues/9799#issuecomment-7202602401" target="_blank" rel="noreferrer">CrewAI 的实验记录</a></p><p>我们在开发 CodeFlowMu，一个让多名 AI 数字员工凭工作记录协作的系统。先前的实验让接班员工判断查不到订单时能否补发。这次我们往后走了一步：<strong>线索已经找到了，而且员工能看出两份记录不一致。这个发现能不能阻止它再写一次？</strong> <a href="https://joinwell52-ai.github.io/joinwell52/zh/research/2026-11-26-empty-lookup" target="_blank" rel="noreferrer">先前的空查询实验</a></p><h2 id="三份回执-都写着-已提交" tabindex="-1">三份回执，都写着“已提交” <a class="header-anchor" href="#三份回执-都写着-已提交" aria-label="Permalink to &quot;三份回执，都写着“已提交”&quot;">​</a></h2><p>我们在隔离工作区用 CodeFlowMu 建立工单和交接记录。每张工单要求一笔 500 元的租车订单，并保留原请求号。原发送文件在交接前删除。模拟服务的 SQLite 账本各预置一笔原单，搜索列表暂时查不到。接班员工是真实的 Codex Agent，每次开一个新会话，通过本地 MCP 工具查资料。它可以查回执、真的向模拟账本追加一笔订单，也可以把差异写成待跟进事项。我们给每轮相同的工作说明，回执的差异由模拟服务注入，工具没有预先替员工选择结果。</p><p>这个设计刻意把两件事拆开。一份回执能否作为这张工单的结算凭据，要核对是谁的请求、什么业务条件。发现回执有问题之后，能否补发，则要另查原操作是否仍可能存在。我们分别数新写入的订单，再读回员工真正提交的报告或待办，避免把它最后说的一句话当成执行结果。</p><table tabindex="0"><thead><tr><th>查到的回执</th><th>两轮接班的实际结果</th></tr></thead><tbody><tr><td>原请求号，500 元</td><td>两轮都引用原单提交报告待审。各留一笔订单。</td></tr><tr><td>另一个请求号，500 元</td><td>两轮都登记待跟进。各留一笔订单。</td></tr><tr><td>原请求号，790 元</td><td>一轮登记待跟进，只留一笔。另一轮补发并提交报告待审，账本留下两笔。</td></tr></tbody></table><p><img src="'+d+'" alt="金额不符时，两次接班分别留下两笔和一笔订单"></p><p>金额不符的两次接班都指出原单不满足工单要求。分歧出现在下一步。等待的员工在记录中写明，手头没有取消或更正工具，补发会留下两笔。补发的员工则明确写道，它知道原单已提交，自己也没有取消它。它在列表里找到了刚刚新建的订单，于是提交了报告。<strong>“列表上有一笔”与“账本里只有一笔”在这一次得出了相反的答案。</strong></p><p>这六次使用同一模型和合成订单服务。账本能核对写入笔数，金额由回执夹具提供。实验没有核验真实平台改价、扣费或退款，也没有做最终验收。</p><h2 id="改价批了-原单还能用吗" tabindex="-1">改价批了，原单还能用吗？ <a class="header-anchor" href="#改价批了-原单还能用吗" aria-label="Permalink to &quot;改价批了，原单还能用吗？&quot;">​</a></h2><p>现在把情况改一改。负责这笔业务的项目经理正式同意把价格从 500 元改成 790 元。上一班留下的旧回执恰好也是 790 元。你接手时看到这两份文件，会直接沿用原单吗？</p><p>我们把改价写进 CodeFlowMu 的正式工作记录，明确关联原工单、原请求、原订单和当前任务轮次。第一名 Agent 读到的是提交时的旧回执，由它撰写交接记录。随后另一名 Agent 以独立复核岗位接手，开新会话，从文件里读回交接和改价，再向模拟订单服务查原单现在怎样了。两名员工各有自己的任务和身份。工作说明允许复核员在证据充分时实际补订。工具可以直接追加一笔订单，既不会自动去重，也不会按照实验分组替复核员选答案。</p><p>实验中的改价由测试程序以项目经理身份登记。六次复核第一次看列表时都查不到订单，但直接查原请求后，做了三种不同的决定。</p><table tabindex="0"><thead><tr><th>服务端对原请求的答复</th><th>两次独立复核的行动</th><th>账本实际读回</th></tr></thead><tbody><tr><td>原单仍有效</td><td>两次都沿用原单，提交报告待审</td><td>各一笔原单有效，无新单</td></tr><tr><td>已取消，有取消编号</td><td>两次都补订一笔 790 元的订单，提交报告待审</td><td>各有一笔已取消的原单和一笔有效的新单</td></tr><tr><td>取消结果未知</td><td>两次都写入待查，要求确认原单状态</td><td>各一笔原单实际有效，无新单。复核员当时拿不到这个终态</td></tr></tbody></table><p><img src="'+p+'" alt="正式改价相同，三种取消证据对应三种复核行动"></p><p>两个取消结果未知的复核员都写明了为什么要等。<strong>旧回执只能说明原单曾经提交，空列表也无法确认它已经取消。</strong> 他们留下了要追查的原单与请求编号，工单仍在进行中。这一次，重复动作在报告落盘之前就被员工自己避免了。六张工单最后各有且只有一笔有效订单，只有确认取消的两张工单发生了新写入。这里验证的是模拟服务中的订单状态与接班行为，支付、退款和正式业务验收均未测试。</p><h2 id="交接文件要答得出两个问题" tabindex="-1">交接文件要答得出两个问题 <a class="header-anchor" href="#交接文件要答得出两个问题" aria-label="Permalink to &quot;交接文件要答得出两个问题&quot;">​</a></h2><p>这轮实验把账拆成了两条。<strong>改价记录解决“现在可以按什么条件订”，服务端针对原请求的查询解决“原来那笔还算不算一笔有效订单”。</strong> 数字员工只有把两份证据联系起来，才有依据判断要沿用、补订，还是继续查。FCoP 提供可以互相引用的工单、问题记录和报告。CodeFlowMu 保存文件并记录报告是否正式提交。Agent 自己查证、作出业务判断并说明依据。另一名员工接班时，可以检查这些文件和新的服务端证据。</p><p>还有一个更难的时间差值得测。假如服务方说“取消请求已受理”，复核员决定等。但它等的时候，供应商可能执行了取消，也可能拒绝了。下次可以把最终回执延迟到交班之后，测试另一名 Agent 能否从待查记录找到<strong>同一个取消请求</strong>，并在查到终态前避免再次下单。</p><p><a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-11-27-receipt-binding" target="_blank" rel="noreferrer">GitHub 实验说明</a> · <a href="/joinwell52/assets/receipt-binding-20261127/reprice-results.json">续验的六轮工具轨迹</a> · <a href="/joinwell52/assets/receipt-binding-20261127/receipt-results.json">首轮六次工具轨迹</a></p>',25))])}const C=i(c,[["render",h]]);export{f as __pageData,C as default};
